def hidden_rule_fn(state):
    n = len(state)
    next_state = [row[:] for row in state]
    for r in range(n):
        for c in range(n):
            s = state[r][c]
            cv = cs = cb = cf = 0
            for dr, dc in [(1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1)]:
                nr, nc = (r+dr) % n, (c+dc) % n
                v = state[nr][nc]
                if v == 0: cv += 1
                elif v == 1: cs += 1
                elif v == 2: cb += 1
                elif v == 3: cf += 1
            mx = max(cv, cs, cb, cf)
            if cv == mx and cv > cf:
                next_state[r][c] = (s + 1) % 4
            elif cf == mx and cf > cv:
                next_state[r][c] = (s - 1) % 4
            else:
                next_state[r][c] = s
    return next_state
